def seedbase(db: Session) -> None:
    existing = {p.name: p for p in db.scalars(select(baseprod)).all()}
    for pr in baseprods:
        ex = existing.get(pr["name"])
        if ex is None:
            db.add(baseprod(**pr))
        else:
            for k, v in pr.items():
                setattr(ex, k, v)
    db.commit()
